#include <iostream>
#include <vector>

std::vector<int> fish = {2, 4, 6, 8, 10};

int line_find(int target) {
    int tries = 0;
    for (int i = 0; i < fish.size(); i++) {
        tries++;
        if (fish[i] == target) {
            return tries;
        }
    }
    return -tries;
}

int half_find(int target) {
    int lo = 0;
    int hi = fish.size() - 1;
    int tries = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        tries++;
        if (fish[mid] == target) {
            return tries;
        } else if (fish[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -tries;
}

int main() {
    std::vector<int> targets = {10, 2};
    for (int i = 0; i < targets.size(); i++) {
        int t = targets[i];
        int a = line_find(t);
        int b = half_find(t);
        std::cout << "找 " << t << "：挨着看 " << (a < 0 ? -a : a) << " 次" << (a < 0 ? "没找到" : "")
                  << "，砍一半 " << (b < 0 ? -b : b) << " 次" << (b < 0 ? "没找到" : "") << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>

const int SLOTS = 10;

std::vector<int> shelf(SLOTS, 0);
std::vector<int> used(SLOTS, 0);

int slot_of(int id) {
    return id % SLOTS;
}

void put(int id) {
    int slot = slot_of(id);
    while (used[slot]) {
        slot = (slot + 1) % SLOTS;
    }
    shelf[slot] = id;
    used[slot] = 1;
}

int find(int id) {
    int slot = slot_of(id);
    int tries = 0;
    while (used[slot]) {
        tries++;
        if (shelf[slot] == id) {
            return tries;
        }
        slot = (slot + 1) % SLOTS;
    }
    return 0;
}

int main() {
    put(4);
    put(14);
    put(6);

    std::cout << "找 14：比了 " << find(14) << " 次\n";
    std::cout << "找 6：比了 " << find(6) << " 次\n";
    std::cout << "找 9：比了 " << find(9) << " 次\n";
    return 0;
}
